adm_id IS NULL OR x.hadm_id=k.hadm_id) AS link_ok, x.valuenum IS NOT NULL AND x.valuenum::text NOT IN('NaN','Infinity','-Infinity') AS finite_ok, lower(regexp_replace(COALESCE(x.valueuom,''),'\s','','g'))=ANY(m.mimic_units) AS unit_ok, x.storetime IS NOT NULL AND GREATEST(x.charttime,x.storetime)<=k.landmark_time AS available_ok, (CASE WHEN m.low_inclusive THEN x.valuenum>=m.low ELSE x.valuenum>m.low END) AND (CASE WHEN m.high_inclusive THEN x.valuenum<=m.high ELSE x.valuenum<m.high END) AS bounds_ok, (x.storetime IS NULL) AS missing_availability, (x.storetime IS NOT NULL AND GREATEST(x.charttime,x.storetime)>k.landmark_time) AS late_availability FROM k JOIN landmark_mimic48.labevents x ON x.subject_id=k.subject_id AND x.charttime BETWEEN k.intime AND k.landmark_time JOIN m ON x.itemid=ANY(m.itemids)), g AS (SELECT key,variable,count(*) AS events, bool_or(link_ok) AS linked,bool_or(link_ok AND finite_ok) AS numeric, bool_or(link_ok AND finite_ok AND unit_ok) AS units, bool_or(link_ok AND finite_ok AND unit_ok AND available_ok) AS timely, bool_or(link_ok AND finite_ok AND unit_ok AND available_ok AND bounds_ok) AS valid, count(*) FILTER(WHERE link_ok AND missing_availability) AS missing_availability_events, count(*) FILTER(WHERE link_ok AND late_availability) AS late_availability_events FROM raw GROUP BY key,variable), features AS MATERIALIZED (SELECT k.key,x.variable,x.observed FROM k JOIN landmark_mimic48.core_features_candidate_v1 f ON f.stay_id=k.key AND f.landmark_hours=24 CROSS JOIN LATERAL(VALUES ('phosphate',f.phosphate IS NOT NULL),('magnesium',f.magnesium IS NOT NULL),('lactate',f.lactate IS NOT NULL),('albumin',f.albumin IS NOT NULL),('platelets',f.platelets IS NOT NULL),('bicarbonate',f.bicarbonate IS NOT NULL))x(variable,observed)) SELECT 'MIMIC' AS dataset,'source_training' AS sample,m.variable, count(*) AS patients,37872 AS expected_patients, count(*) FILTER(WHERE g.events>0) AS any_imported_event_patients, count(*) FILTER(WHERE g.linked) AS linked_event_patients, count(*) FILTER(WHERE g.numeric) AS finite_numeric_patients, count(*) FILTER(WHERE g.units) AS compatible_unit_patients, count(*) FILTER(WHERE g.timely) AS available_by_24h_patients, count(*) FILTER(WHERE g.valid) AS screened_available_patients, count(*) FILTER(WHERE f.observed) AS final_observed_patients, count(*) FILTER(WHERE COALESCE(g.valid,false) IS DISTINCT FROM f.observed OR f.observed IS NULL) AS feature_presence_mismatches, COALESCE(sum(g.events),0) AS imported_event_rows, COALESCE(sum(g.missing_availability_events),0) AS missing_availability_event_rows, COALESCE(sum(g.late_availability_events),0) AS late_availability_event_rows FROM k CROSS JOIN m LEFT JOIN g ON g.key=k.key AND g.variable=m.variable LEFT JOIN features f ON f.key=k.key AND f.variable=m.variable GROUP BY m.variable ORDER BY m.variable) TO 'C:/Users/Lenovo/Documents/Ujjwal/Masters application/research/model_results/pruning_focused_amendment_2026_10_29_v1/MIMIC_harmonization_funnel.csv' WITH(FORMAT csv,HEADER true)
