nite_ok, lower(regexp_replace(replace(COALESCE(x.labmeasurenamesystem,''),'µ','u'),'[[:space:]]','','g'))=ANY(m.eicu_units) AND (COALESCE(x.labmeasurenameinterface,'')='' OR lower(regexp_replace(replace(COALESCE(x.labmeasurenameinterface,''),'µ','u'),'[[:space:]]','','g'))=ANY(m.eicu_units)) AS unit_ok, x.labresultrevisedoffset IS NOT NULL AND GREATEST(x.labresultoffset,x.labresultrevisedoffset)<=1440 AS available_ok, (CASE WHEN m.low_inclusive THEN x.labresult>=m.low ELSE x.labresult>m.low END) AND (CASE WHEN m.high_inclusive THEN x.labresult<=m.high ELSE x.labresult<m.high END) AS bounds_ok, (x.labresultrevisedoffset IS NULL) AS missing_availability, (x.labresultrevisedoffset IS NOT NULL AND GREATEST(x.labresultoffset,x.labresultrevisedoffset)>1440) AS late_availability FROM k JOIN eicu_landmark.core_lab_source_v1 x ON x.patientunitstayid=k.key AND x.labresultoffset BETWEEN 0 AND 1440 JOIN m ON x.labname=m.labname), g AS (SELECT key,variable,count(*) AS events, bool_or(link_ok) AS linked,bool_or(link_ok AND finite_ok) AS numeric, bool_or(link_ok AND finite_ok AND unit_ok) AS units, bool_or(link_ok AND finite_ok AND unit_ok AND available_ok) AS timely, bool_or(link_ok AND finite_ok AND unit_ok AND available_ok AND bounds_ok) AS valid, count(*) FILTER(WHERE link_ok AND missing_availability) AS missing_availability_events, count(*) FILTER(WHERE link_ok AND late_availability) AS late_availability_events FROM raw GROUP BY key,variable), features AS MATERIALIZED (SELECT k.key,x.variable,x.observed FROM k JOIN eicu_landmark.core_features_candidate_v3 f ON f.patientunitstayid=k.key AND f.landmark_hours=24 CROSS JOIN LATERAL(VALUES ('phosphate',f.phosphate IS NOT NULL),('magnesium',f.magnesium IS NOT NULL),('lactate',f.lactate IS NOT NULL),('albumin',f.albumin IS NOT NULL),('platelets',f.platelets IS NOT NULL),('bicarbonate',f.bicarbonate IS NOT NULL))x(variable,observed)) SELECT 'eICU' AS dataset,'target_adaptation' AS sample,m.variable, count(*) AS patients,20589 AS expected_patients, count(*) FILTER(WHERE g.events>0) AS any_imported_event_patients, count(*) FILTER(WHERE g.linked) AS linked_event_patients, count(*) FILTER(WHERE g.numeric) AS finite_numeric_patients, count(*) FILTER(WHERE g.units) AS compatible_unit_patients, count(*) FILTER(WHERE g.timely) AS available_by_24h_patients, count(*) FILTER(WHERE g.valid) AS screened_available_patients, count(*) FILTER(WHERE f.observed) AS final_observed_patients, count(*) FILTER(WHERE COALESCE(g.valid,false) IS DISTINCT FROM f.observed OR f.observed IS NULL) AS feature_presence_mismatches, COALESCE(sum(g.events),0) AS imported_event_rows, COALESCE(sum(g.missing_availability_events),0) AS missing_availability_event_rows, COALESCE(sum(g.late_availability_events),0) AS late_availability_event_rows FROM k CROSS JOIN m LEFT JOIN g ON g.key=k.key AND g.variable=m.variable LEFT JOIN features f ON f.key=k.key AND f.variable=m.variable GROUP BY m.variable ORDER BY m.variable) TO 'C:/Users/Lenovo/Documents/Ujjwal/Masters application/research/model_results/pruning_focused_amendment_2026_10_29_v1/eICU_harmonization_funnel.csv' WITH(FORMAT csv,HEADER true)
